        """
        SELECT DISTINCT d.*
        FROM devices d
        LEFT JOIN device_shares s
          ON s.device_id = d.id AND s.account_id = ?
        WHERE d.owner_account_id = ? OR s.id IS NOT NULL
        ORDER BY d.id
        """,
        (caller_id, caller_id),
